q=add('sql-paid-revenue','Revenue without losing customers','code','SQL','sql-editor','Return customer_id, name and revenue for every customer. Sum only paid orders; customers with no paid orders must have revenue 0. Sort by customer_id.','SELECT c.customer_id, c.name,\n       0 AS revenue\nFROM customers AS c\nORDER BY c.customer_id;',"SELECT c.customer_id, c.name, COALESCE(SUM(o.amount),0) AS revenue\nFROM customers c\nLEFT JOIN orders o ON c.customer_id=o.customer_id AND o.status='paid'\nGROUP BY c.customer_id,c.name\nORDER BY c.customer_id;",'Putting paid status inside ON preserves the null-extended customer row. COALESCE turns a missing sum into zero. The output grain is one customer, not one order.',['Keep every customer.','Exclude cancelled and pending orders.','Use exact output column names and customer_id ordering.'],legacy=True,difficulty='Easy',ordered=True,dataset='retail',visual=dict(type='sql-join-trace',steps=['4 customers','LEFT JOIN paid orders','5 joined rows','GROUP BY customer','4 customer totals'],detail='Ada matches two paid orders; Cleo and Dan keep one NULL-extended row each. A WHERE filter on o.status would remove them.'))
add('sql-latest-order','The latest order, with a tie-breaker','code','SQL','sql-editor','Return customer_id, order_id and order_date for the latest order per customer. Break date ties with the greatest order_id. Sort by customer_id.',"WITH ranked AS (\n SELECT *, ROW_NUMBER() OVER (\n  PARTITION BY customer_id\n  ORDER BY order_date DESC\n ) AS rn FROM orders\n)\nSELECT customer_id,order_id,order_date\nFROM ranked WHERE rn=1 ORDER BY customer_id;", "WITH ranked AS (\n SELECT *, ROW_NUMBER() OVER (\n  PARTITION BY customer_id ORDER BY order_date DESC,order_id DESC\n ) AS rn FROM orders\n)\nSELECT customer_id,order_id,order_date FROM ranked WHERE rn=1 ORDER BY customer_id;",'ROW_NUMBER preserves every candidate while calculating rank. Filtering rn = 1 changes the grain to one row per customer. A stable tie-breaker prevents arbitrary selection.',['Partition by customer_id.','Order by descending date, then descending order_id.','Do not return customers without orders.'],legacy=True,ordered=True,dataset='retail',visual=dict(type='sql-window',steps=['Partition by customer','Order date DESC, ID DESC','Assign row numbers','Keep rn = 1'],detail='For equal dates, the greatest order_id wins. Window ORDER BY does not set final display order.'))
add('python-aggregate','Turn event rows into a dictionary','code','Python','code-editor','Implement solve(events): sum amount by country into a dictionary. Empty input returns {}. Do not mutate input.','def solve(events):\n    totals = {}\n    for event in events:\n        pass\n    return totals','def solve(events):\n    totals = {}\n    for event in events:\n        key = event["country"]\n        totals[key] = totals.get(key, 0) + event["amount"]\n    return totals','Each event is visited once: O(n) time, O(k) memory for k countries. The first occurrence needs an initial zero.',['Do not mutate input.','Include zero and negative amounts.','Use country as dictionary key.'],legacy=True,difficulty='Easy',entrypoint='solve',pythonTests=[dict(label='Two countries',args=[[dict(country='NO',amount=10),dict(country='SE',amount=5),dict(country='NO',amount=7)]],expected={'NO':17,'SE':5}),dict(label='Empty',args=[[]],expected={}),dict(label='Refund',args=[[dict(country='NO',amount=0),dict(country='NO',amount=-2)]],expected={'NO':-2})],visual=dict(type='python-data-flow',steps=['Event rows','Read country key','get(key, 0) + amount','Dictionary of totals'],detail='A list contains events; a dictionary indexes their accumulated totals.'))
add('python-two-sum','Find the matching pair','code','Python','code-editor','Implement solve(numbers,target). Return increasing indices of the only valid pair, or [] when none exists. Do not reuse an index.','def solve(numbers, target):\n    seen = {}\n    for index, value in enumerate(numbers):\n        pass\n    return []','def solve(numbers, target):\n    seen = {}\n    for index, value in enumerate(numbers):\n        other = target - value\n        if other in seen:\n            return [seen[other], index]\n        seen[value] = index\n    return []','Check the complement before inserting the current number. That permits duplicate values at different indices without reusing one element.',['Distinct indices.','Handle duplicate and negative values.','Aim for one pass.'],legacy=True,difficulty='Easy',entrypoint='solve',pythonTests=[dict(label='Pair',args=[[2,7,11,15],9],expected=[0,1]),dict(label='Duplicate',args=[[3,3],6],expected=[0,1]),dict(label='Negative',args=[[-2,5,3],1],expected=[0,2]),dict(label='No match',args=[[1,2],10],expected=[])])
