add('spark-dedup','Deduplicate events deterministically','code','PySpark','pyspark-editor','Keep the latest event per customer, breaking event_time ties by descending event_id. Explain why dropDuplicates(["customer_id"]) does not express this rule.','from pyspark.sql import functions as F, Window\n\nw = Window.partitionBy("customer_id")\n# Add order, row_number, filter and drop.', 'from pyspark.sql import functions as F, Window\n\nw = Window.partitionBy("customer_id").orderBy(\n    F.col("event_time").desc(), F.col("event_id").desc()\n)\nresult = (events.withColumn("rn", F.row_number().over(w))\n          .filter(F.col("rn") == 1).drop("rn"))','A DataFrame has no implicit reliable row order. The window expresses a deterministic business rule but generally needs redistribution and sorting. This page never executes Spark.',['Partition by customer_id.','Both ordering columns descending.','Keep rn = 1 and remove the helper.'],legacy=True,fixture=spark_fixture,visual=dict(type='pyspark-transformations',steps=['3 input events','Exchange by customer','Sort within partition','Window row_number','2 latest events'],detail='Exchange is a shuffle boundary. SQL ROW_NUMBER and this PySpark window express the same latest-record rule.'))
add('tsql-running-total','A running total in T-SQL','code','T-SQL','sql-editor','Write a T-SQL running_amount by customer with order_date and order_id ordering. Explain ROWS versus RANGE peers. This is dialect review, not DuckDB execution.','SELECT order_id, customer_id,\n SUM(amount) OVER (\n  PARTITION BY customer_id\n  -- ordering and frame\n ) AS running_amount\nFROM orders;', 'SELECT order_id, customer_id,\n SUM(amount) OVER (\n  PARTITION BY customer_id ORDER BY order_date, order_id\n  ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW\n ) AS running_amount\nFROM orders;','ROWS counts physical rows in the declared order. RANGE uses value peers; duplicated dates can extend the frame together. A stable ordering key makes row-by-row intent explicit.',['Partition by customer.','Use an explicit ROWS frame.','Discuss duplicate dates.'],legacy=True,language='T-SQL',visual=dict(type='sql-window',steps=['Customer partition','Date + ID order','ROWS frame','Cumulative SUM'],detail='The final SELECT display order is separate from the window order.'))['engine']='review'
add('bigquery-qualify','Latest events with QUALIFY','code','BigQuery','sql-editor','Select the latest event per customer from analytics.events using QUALIFY. State whether latest means all time or inside a date range.','SELECT *\nFROM `analytics.events`\nQUALIFY -- window condition', 'SELECT *\nFROM `analytics.events`\nQUALIFY ROW_NUMBER() OVER (\n PARTITION BY customer_id ORDER BY event_time DESC,event_id DESC\n) = 1;','QUALIFY filters window results. A WHERE date filter changes candidate rows before ranking; do not introduce one without clarifying the business scope.',['ROW_NUMBER with QUALIFY.','Deterministic tie-breaker.','State date scope.'],legacy=True,language='BigQuery SQL')['engine']='review'
add('pandas-grain','Group a DataFrame without losing its meaning','code','pandas','code-editor','Implement solve(rows): construct a DataFrame and return records with customer_id, total_amount, line_count, sorted by customer_id. Count rows including missing amounts. Empty input returns [].','def solve(rows):\n    import pandas as pd\n    if not rows:\n        return []\n    lines = pd.DataFrame(rows)\n    # Named aggregation, then to_dict("records")\n    return []', 'def solve(rows):\n    import pandas as pd\n    if not rows:\n        return []\n    lines = pd.DataFrame(rows)\n    return (lines.groupby("customer_id", as_index=False)\n            .agg(total_amount=("amount", "sum"),\n                 line_count=("amount", "size"))\n            .sort_values("customer_id").to_dict("records"))','size counts rows while count excludes null values in the chosen column. This exercise has non-null customer IDs; discuss dropna=False separately for missing keys.',['One row per customer.','Sum amount; size for row count.','Return JSON-compatible records.'],legacy=True,difficulty='Easy',entrypoint='solve',pythonTests=[dict(label='Null amount counts as a row',args=[[dict(customer_id=1,amount=10),dict(customer_id=1,amount=None),dict(customer_id=2,amount=7)]],expected=[dict(customer_id=1,total_amount=10,line_count=2),dict(customer_id=2,total_amount=7,line_count=1)]),dict(label='Empty input',args=[[]],expected=[])],fixture={'packages':['pandas']})
