add('v2-sql-quality','Detect duplicate keys before a merge','code','SQL','sql-editor','Return customer_id and duplicate_count for customer IDs appearing more than once in orders. Sort by customer_id.','SELECT customer_id\nFROM orders\n-- Group and filter duplicate keys', 'SELECT customer_id, COUNT(*) AS duplicate_count\nFROM orders GROUP BY customer_id HAVING COUNT(*) > 1\nORDER BY customer_id;', 'GROUP BY changes row grain. HAVING filters groups after aggregation. A MERGE source may need deterministic deduplication, not just detection.',['Use COUNT(*) not COUNT(amount).','Filter groups with more than one row.','State the source grain.'],difficulty='Easy',ordered=True,dataset='retail')
add('v2-sql-cte','Customers above average paid spend','code','SQL','sql-editor','Return customer_id and revenue for customers whose paid total exceeds the average of paid totals among customers with at least one paid order. Sort by customer_id.','WITH totals AS (\n -- paid total per customer\n)\nSELECT * FROM totals;',"WITH totals AS (\n SELECT customer_id, SUM(amount) AS revenue\n FROM orders WHERE status='paid' GROUP BY customer_id\n)\nSELECT customer_id,revenue FROM totals\nWHERE revenue > (SELECT AVG(revenue) FROM totals)\nORDER BY customer_id;",'Compute the average at the customer-total grain, not the raw order grain. Customers without paid orders are excluded from this specifically defined average.',['Filter paid orders before grouping.','Average customer totals, not order amounts.','Do not silently include zero-spend customers.'],ordered=True,dataset='retail')
add('v2-python-batches','Batch records without losing the final chunk','code','Python','code-editor','Implement solve(records,size). Return batches as lists. A final short batch must be kept; size <= 0 raises ValueError (tested separately in explanation).','def solve(records, size):\n    # Validate size and return batches\n    return []','def solve(records, size):\n    if size <= 0:\n        raise ValueError("size must be positive")\n    return [records[i:i + size] for i in range(0, len(records), size)]','Slice boundaries naturally keep the short final batch. A generator variant can reduce retained output memory but does not by itself make a materialized source streaming.',['Keep the final short batch.','Do not mutate records.','Handle empty input.'],difficulty='Easy',entrypoint='solve',pythonTests=[dict(label='Remainder',args=[[1,2,3,4,5],2],expected=[[1,2],[3,4],[5]]),dict(label='Empty',args=[[],3],expected=[]),dict(label='One large batch',args=[[1,2],9],expected=[[1,2]])])
add('v2-python-latest','Latest revision from API records','code','Python','code-editor','Implement solve(records). Keep the highest revision for each id and return records sorted by id. Equal revisions keep the first record.','def solve(records):\n    latest = {}\n    # Key by id; compare revision\n    return []','def solve(records):\n    latest = {}\n    for row in records:\n        old = latest.get(row["id"])\n        if old is None or row["revision"] > old["revision"]:\n            latest[row["id"]] = row\n    return [latest[k] for k in sorted(latest)]','A dictionary stores one candidate per key. Using > rather than >= makes the tie policy explicit. Return records without mutating input.',['One record per id.','Highest revision wins.','First wins equal revisions.'],entrypoint='solve',pythonTests=[dict(label='Out of order',args=[[dict(id=2,revision=1),dict(id=1,revision=2),dict(id=1,revision=1)]],expected=[dict(id=1,revision=2),dict(id=2,revision=1)]),dict(label='Stable tie',args=[[dict(id=1,revision=1,value='first'),dict(id=1,revision=1,value='second')]],expected=[dict(id=1,revision=1,value='first')]),dict(label='Empty',args=[[]],expected=[])])
add('v2-spark-aggregate','Revenue and event count in PySpark','code','PySpark','pyspark-editor','Build result with customer_id, revenue and event_count from events. Use built-in aggregations; count rows even when amount is null.','from pyspark.sql import functions as F\n\nresult = (events\n    .groupBy("customer_id")\n    # Add named aggregates\n)', 'from pyspark.sql import functions as F\nresult = (events.groupBy("customer_id")\n .agg(F.sum("amount").alias("revenue"),\n      F.count("*").alias("event_count")))','groupBy causes an aggregation shuffle unless compatible partitioning already satisfies the plan. count("*") counts rows; count("amount") excludes null amounts. This is review, never browser Spark execution.',['Group by customer_id.','Built-in sum, not Python UDF.','Count all rows.'],difficulty='Easy',fixture={**spark_fixture,'expected':[dict(customer_id=1,revenue=25,event_count=2),dict(customer_id=2,revenue=7,event_count=1)],'plan':'Scan -> partial HashAggregate -> Exchange customer_id -> final HashAggregate'},visual=dict(type='pyspark-transformations',steps=['3 events','Partial aggregate','Exchange by key','Final aggregate','2 customers'],detail='Built-in aggregations expose the work to the Spark optimizer.'))
add('v2-spark-join','A left join that preserves unmatched facts','code','PySpark','pyspark-editor','Enrich events with a small customer dimension by customer_id. Keep unmatched events and explain why duplicate dimension keys would multiply facts.','from pyspark.sql import functions as F\n\n# Enrich events using customers', 'result = events.join(F.broadcast(customers), "customer_id", "left")\n# Validate customer_id uniqueness in customers before trusting row counts.', 'Broadcasting is a plan choice, not a correctness guarantee. The dimension must fit broadcast memory and have the intended key uniqueness. A left join preserves facts but can still multiply them.',['Left join, not inner.','Check dimension uniqueness.','Validate size before broadcasting.'],fixture={**spark_fixture,'tables':{'events':spark_events,'customers':[dict(customer_id=1,country='NO')]},'expected':[{**r,'country':'NO' if r['customer_id']==1 else None} for r in spark_events],'plan':'Illustrative: Scan events -> BroadcastHashJoin LeftOuter <- BroadcastExchange customers'},visual=dict(type='sql-join-trace',steps=['3 facts','1 unique dimension key','Left broadcast join','3 enriched facts'],detail='An inner join would drop customer 2; duplicate dimension keys would multiply customer 1 events.'))
add('v2-airflow-branch','Join after a skipped branch','pipeline','Airflow','dag-editor','The optional branch is skipped. Configure the final join so that it runs when at least one parent succeeds and none failed. Compare all_success and none_failed_min_one_success.','# Use synchronized graph/config for trigger rules.','Set join.triggerRule to none_failed_min_one_success. Do not use all_done when a failed prerequisite must block publication.','A skipped branch is not a failure, but all_success will not accept it. none_failed_min_one_success encodes the desired condition.',['Require at least one successful parent.','Block actual failures.','Do not treat skipped as success.'],fixture={'graph':{'nodes':[{'id':'extract','label':'Extract','role':'task','x':30,'y':40},{'id':'required','label':'Required branch','role':'task','x':260,'y':40},{'id':'optional','label':'Optional branch','role':'task','x':260,'y':190,'skip':True},{'id':'join','label':'Publish join','role':'task','x':490,'y':100,'triggerRule':'all_success'}],'edges':[{'id':'e1','from':'extract','to':'required'},{'id':'e2','from':'extract','to':'optional'},{'id':'e3','from':'required','to':'join'},{'id':'e4','from':'optional','to':'join'}]},'targetTask':'join'})
add('v2-dbt-failure','Follow a failing dbt build artifact','pipeline','dbt','pipeline-investigation','A uniqueness test on stg_orders failed. Inspect the artifact-shaped fixtures and explain why revenue must not be published. Repair the SQL deduplication approach in your answer.','WITH ranked AS (\n SELECT *, ROW_NUMBER() OVER (\n  PARTITION BY order_id ORDER BY updated_at DESC, ingestion_id DESC\n ) AS rn\n FROM {{ source("raw", "orders") }}\n)\n-- Keep one deterministic row', 'SELECT * EXCLUDE(rn) FROM ranked WHERE rn = 1;\n-- Then rerun unique/not_null tests and validate fact grain before publication.', 'A failed test needs an investigation into source grain and change semantics. Silently dropping duplicates can hide upstream contract errors. These fixtures do not compile Jinja or execute dbt.',['Identify the failing node.','Trace affected downstream consumers.','State a deterministic latest-record and test policy.'],fixture={'manifest':{'metadata':{'dbt_schema_version':'https://schemas.getdbt.com/dbt/manifest/v12.json','note':'Curated subset, not a full manifest'},'nodes':{'model.demo.stg_orders':{'resource_type':'model','depends_on':{'nodes':['source.demo.raw.orders']},'config':{'materialized':'view'}},'test.demo.unique_stg_orders':{'resource_type':'test','depends_on':{'nodes':['model.demo.stg_orders']}},'model.demo.fct_revenue':{'resource_type':'model','depends_on':{'nodes':['model.demo.stg_orders']},'config':{'materialized':'incremental','unique_key':'customer_id'}}}},'run_results':{'results':[{'unique_id':'model.demo.stg_orders','status':'success','execution_time':1.2},{'unique_id':'test.demo.unique_stg_orders','status':'fail','failures':2},{'unique_id':'model.demo.fct_revenue','status':'skipped','execution_time':0}]},'graph':{'nodes':[{'id':'raw','label':'raw.orders','role':'source','x':30,'y':40},{'id':'staging','label':'stg_orders','role':'model','x':260,'y':40},{'id':'test','label':'unique(order_id)','role':'test fail: 2','x':490,'y':40},{'id':'mart','label':'fct_revenue','role':'skipped','x':260,'y':190}],'edges':[{'id':'a','from':'raw','to':'staging'},{'id':'b','from':'staging','to':'test'},{'id':'c','from':'staging','to':'mart'}]}})
add('v2-spark-files','Small files without a fake speed estimate','architecture','Spark performance','performance-investigation','Inspect this file-heavy stage. Distinguish scheduling and file-open overhead from a skew claim. Explain a compaction plan and how to measure improvement.','# Diagnosis and measurement plan','Many tiny files and comparable task durations suggest investigating file/listing overhead. Compact to a workload-appropriate file size and measure metadata time, scan tasks and bytes. Avoid promising a universal target size or exact speedup.','The absence of a long task tail weakens a skew diagnosis here. File layout choices depend on write frequency, downstream queries and partition pruning.',['Use file and task evidence.','Do not claim skew without a distribution.','Measure scan overhead before and after.'],fixture={'metrics':{'Input':'8 GB','Files':'80,000','Median file':'100 KB','Tasks':'80,000','Median task':'0.6 s','Slowest task':'0.9 s','Spill':'0 GB','Scheduler delay':'Fixture indicates high overhead'},'tasks':[dict(task=i,duration_s=.5+i*.04,read_GB=.0001,spill_GB=0) for i in range(1,9)],'plan':'FileScan parquet [date partition] -> Project -> Write','diagnoses':[{'id':'files','label':'Investigate small-file and scheduling overhead','correct':True},{'id':'compact','label':'Evaluate compaction and measure scan overhead','correct':True},{'id':'skew','label':'The evidence proves a hot-key skew problem','correct':False}]})
add('v2-tofu-replacement','Review a destructive replacement plan','architecture','OpenTofu','config-editor','The plan fixture replaces a storage bucket after a name change. Identify delete/create, explain state implications, and add a prevent_destroy safeguard to the example HCL.','resource "aws_s3_bucket" "lake" {\n  bucket = "analytics-lake-v2"\n}', 'resource "aws_s3_bucket" "lake" {\n  bucket = "analytics-lake-v2"\n  lifecycle { prevent_destroy = true }\n}\n# Investigate a migration rather than blindly applying replacement.', 'prevent_destroy blocks destructive plans while the configuration remains applicable; it is not a backup. The plan is a fixed JSON fixture and is not recomputed when you edit HCL.',['Identify delete/create replacement.','Do not run apply.','Protect data and design migration.'],fixture={'plan':{'format_version':'1.2','resource_changes':[{'address':'aws_s3_bucket.lake','change':{'actions':['delete','create'],'before':{'bucket':'analytics-lake-v1'},'after':{'bucket':'analytics-lake-v2'},'replace_paths':[['bucket']]}}]},'checks':[{'label':'Destruction safeguard is explicit','pattern':'prevent_destroy\\s*=\\s*true'}],'graph':{'nodes':[{'id':'bucket','label':'Bucket replacement','role':'delete + create','x':30,'y':60},{'id':'policy','label':'Access policy','role':'dependent','x':270,'y':60}],'edges':[{'id':'e','from':'bucket','to':'policy'}]}})
add('v2-k8-selector','Why does the Service have no endpoints?','architecture','Kubernetes','config-editor','The Pod template has app: worker, but the Service selects app: api. Repair the selector and describe readiness and port checks.','apiVersion: v1\nkind: Service\nmetadata:\n  name: worker\nspec:\n  selector:\n    app: api\n  ports:\n    - port: 80\n      targetPort: 8080', 'apiVersion: v1\nkind: Service\nmetadata:\n  name: worker\nspec:\n  selector:\n    app: worker\n  ports:\n    - port: 80\n      targetPort: 8080', 'The selector must match pod labels, not merely the Deployment name. Readiness and targetPort must also be checked. This analyzer inspects the fixture pattern, not a Kubernetes API.',['Match app: worker.','Keep targetPort 8080 for the fixture.','Explain readiness separately.'],fixture={'events':[{'reason':'NoEndpoints','message':'Service selector app=api matches 0 pods'},{'reason':'PodReady','message':'worker-7 labels app=worker, port 8080'}],'logs':'worker-7: listening on 0.0.0.0:8080\nreadiness: ok\n','checks':[{'label':'Selector matches the Pod label','pattern':'selector:\\s*\\n\\s*app:\\s*worker'},{'label':'Target port matches listening process','pattern':'targetPort:\\s*8080'}]})
add('v2-docker-cache','Stop reinstalling dependencies for every edit','architecture','Docker','config-editor','The Dockerfile copies all source before installing requirements. Reorder layers for reuse and run the final container as non-root.','FROM python:3.12-slim\nWORKDIR /app\nCOPY . .\nRUN pip install --no-cache-dir -r requirements.txt\nCMD ["python", "pipeline.py"]','FROM python:3.12-slim\nWORKDIR /app\nCOPY requirements.txt .\nRUN pip install --no-cache-dir -r requirements.txt\nCOPY . .\nUSER 10001\nCMD ["python", "pipeline.py"]','Separating the dependency manifest from frequently edited source preserves the install layer when only application code changes. Exclude secrets and irrelevant files using .dockerignore; non-root permissions still need testing.',['Copy requirements before pip install.','Copy changing source after dependency installation.','Use a non-root user.'],fixture={'layers':[{'layer':'FROM python:3.12-slim','invalidated':'Only when base changes'},{'layer':'COPY . .','invalidated':'Any source edit'},{'layer':'RUN pip install','invalidated':'Also invalidated by earlier source copy'}],'checks':[{'label':'Cache-friendly dependency ordering','kind':'docker-order'},{'label':'Non-root user','pattern':'USER\\s+(?!root\\b|0\\b)\\S+'}]},visual=dict(type='docker-layers',steps=['Base image','COPY requirements','Install dependencies','COPY application','Non-root runtime'],detail='A changed layer invalidates subsequent cached layers. Keep frequently changing input later.'))
